let pronunciationAudio=null,pronunciationTimer=null,pronunciationId=0;
const bundledAudio=new Set(['configure','inherit','descend','heredity','heritage','thorn','warrant','embolden','outrage','turmoil','ambivalent','interrogate','eradicate']);
function stopPronunciation(){pronunciationId++;clearTimeout(pronunciationTimer);if(pronunciationAudio){pronunciationAudio.pause();pronunciationAudio=null;}if('speechSynthesis' in window)window.speechSynthesis.cancel();document.querySelectorAll('.pronunciation-button').forEach(b=>b.setAttribute('aria-busy','false'));}
function playPronunciation(word,accent='uk'){
 stopPronunciation();const id=pronunciationId,locale=accent==='us'?'en-US':'en-GB',label=accent==='us'?'US':'UK';
 const button=document.querySelector(accent==='us'?'#speak-us':'#speak'),status=document.querySelector('#audio-status');
 const setStatus=(text,busy=false)=>{if(id!==pronunciationId)return;status.textContent=text;button.setAttribute('aria-busy',String(busy));};
 const failed=()=>setStatus(`${label} audio unavailable. Check your volume or try again.`);
 const speakFallback=()=>{
  if(id!==pronunciationId)return;clearTimeout(pronunciationTimer);
  if(pronunciationAudio){pronunciationAudio.pause();pronunciationAudio=null;}
  if(!('speechSynthesis' in window)){failed();return;}
  const voice=speechSynthesis.getVoices().find(v=>v.lang.replace('_','-').toLowerCase()===locale.toLowerCase());
  if(!voice){failed();return;}
  const u=new SpeechSynthesisUtterance(word);u.lang=locale;u.voice=voice;u.rate=.85;u.volume=1;
  setStatus(`Loading ${label} system voice…`,true);
  u.onstart=()=>setStatus(`Playing ${label} system voice…`,true);u.onend=()=>{clearTimeout(pronunciationTimer);setStatus(`${label} pronunciation`);};u.onerror=()=>{clearTimeout(pronunciationTimer);failed();};
  pronunciationTimer=setTimeout(()=>{if(id===pronunciationId){speechSynthesis.cancel();failed();}},6000);
  speechSynthesis.resume();speechSynthesis.speak(u);
 };
 const src=bundledAudio.has(word)?(accent==='us'?'audio/us/'+encodeURIComponent(word)+'.mp3':'audio/'+encodeURIComponent(word)+(word==='inherit'?'.wav':'.mp3')):'https://dict.youdao.com/dictvoice?audio='+encodeURIComponent(word)+'&type='+(accent==='us'?'2':'1');
 pronunciationAudio=new Audio(src);const a=pronunciationAudio;a.preload='auto';a.volume=1;a.setAttribute('playsinline','');setStatus(`Loading ${label} audio…`,true);
 a.onplaying=()=>{clearTimeout(pronunciationTimer);setStatus(`Playing ${label} pronunciation…`,true);};
 a.onended=()=>setStatus(`${label} pronunciation`);a.onerror=speakFallback;pronunciationTimer=setTimeout(speakFallback,7000);a.play().catch(speakFallback);
}
let lockedScrollY=null;
function showModal(dialog){
 if(lockedScrollY===null){lockedScrollY=window.scrollY;document.documentElement.classList.add('modal-open');document.body.classList.add('modal-open');document.body.style.top=`-${lockedScrollY}px`;}
 dialog.showModal();const content=dialog.querySelector('.body');if(content)content.scrollTop=0;
}
function releaseModalLock(){
 if(document.querySelector('dialog[open]')||lockedScrollY===null)return;
 const y=lockedScrollY;lockedScrollY=null;document.documentElement.classList.remove('modal-open');document.body.classList.remove('modal-open');document.body.style.top='';window.scrollTo(0,y);
}
for(const dialog of document.querySelectorAll('dialog')){
 dialog.addEventListener('close',()=>{if(dialog.id==='detail')stopPronunciation();releaseModalLock();});
 dialog.addEventListener('touchmove',e=>{if(!e.target.closest('.body'))e.preventDefault()},{passive:false});
}
